import {randomUUID} from 'node:crypto';
import type {CurrentSession} from '../../../lib/server/auth/sessions';
import {saveGap,readGap} from '../../../lib/server/gaps/service';
import {saveGapImpact} from '../../../lib/server/gaps/impacts';
import {previewGapDecision,commitGapDecision} from '../../../lib/server/gaps/review';
import {syntheticGap,syntheticImpact} from './ui';
import type {GapContent} from '../../../lib/contracts/product-gaps';
export const gapEnvelope=(expectedVersion=0)=>({contractVersion:'product-gaps-v1' as const,requestKey:randomUUID(),expectedVersion});
export async function reviewedSyntheticGap(author:CurrentSession,reviewer:CurrentSession,overrides:Partial<GapContent>={}){const saved=await saveGap(author,{...gapEnvelope(),content:syntheticGap(overrides),sourceRefs:[],customerIndependentAcknowledgment:true});const preview=await previewGapDecision(reviewer,saved.recordId!,{...gapEnvelope(1),target:'gap',revisionId:saved.resultId,action:'accept',rationale:'Independent synthetic canonical fixture review',revisitDate:null,selfReview:author.membershipId===reviewer.membershipId,customerIndependentAcknowledgment:true});await commitGapDecision(reviewer,saved.recordId!,{...gapEnvelope(1),previewId:preview.resultId,bindingDigest:preview.bindingDigest});return readGap(author,saved.recordId!);}
export async function reviewedSuspectedImpact(author:CurrentSession,reviewer:CurrentSession,gapId:string,customerId:string){const gap=await readGap(author,gapId),saved=await saveGapImpact(author,gapId,{...gapEnvelope(),expectedGapVersion:gap.version,customerId,workloadId:null,engagementId:null,recurrenceParent:null,content:syntheticImpact(),sourceRefs:[]}),detail=await readGap(author,gapId),impact=detail.impacts.find(i=>i.working?.id===saved.resultId)!;const preview=await previewGapDecision(reviewer,gapId,{...gapEnvelope(1),target:'impact',impactId:impact.id,revisionId:saved.resultId,action:'accept',rationale:'Independent synthetic suspected observation review',revisitDate:null,selfReview:author.membershipId===reviewer.membershipId});await commitGapDecision(reviewer,gapId,{...gapEnvelope(1),previewId:preview.resultId,bindingDigest:preview.bindingDigest});return impact.id;}
